async function huntDiversified() {
  // Try to find NPCs that are less common in Lumbridge center
  // Walk to potentially different areas
  await bot.walkTo(3226, 3225); // Near flowers/doors mentioned in state

  const targets = ["Chicken", "Cow", "Zombie", "Goblin", "Imp", "Spider"];
  let killed = [];

  for (const target of targets) {
    const result = await bot.attack(target);
    if (result.success) {
      await sdk.waitForCondition(state => {
        const player = state.player;
        return !player || !player.combat.inCombat;
      }, 30000);
      killed.push(target);
    }
  }
  return killed;
}

return await huntDiversified();

